// Phase 5 slice sweep1, group shop (0x3E9160-0x4175DB): the facility code facility2 left because its callees were
// stood in -- the shop sequence's step callbacks (ROOT fini; the updates of ARMSCOMBINE, TRADE, QUEST,
// QUESTCANCEL, BOOK, BOOKREGIST and the init / fini / update / draw of HELP: the step descriptors 0x6A70B0..
// {init, fini, update, draw, payload size, name}), the item / equipment list builders and their element / row
// drawers (the drawer tables 0x6AEE20 / 0x6AF070 and 0x7CD970), the quantity selector, the request lists and their
// panels (Elizabeth's requests), the compendium lists, the facility sprite helper, the bank / theatre task updates
// of the fcl tasks (0x6B1900..) and the fclCombineEffect task updates.
//
// Generated by p3fes_handgen (one statement per instruction on the hg_cpu register view: frame, spills, $ra links,
// cycle charges and check points exactly as the recompiled bodies) and made readable on top: a role block per
// function (the records are shops.h's and facility2.h's: the shop work record of $gp 0x7CE688, the step payload
// {+0 result, +4 flags, +8 phase, ...}, the list objects of nm_message.h); no statement moved, added or dropped
// (checked against the generator's output). tests/game/test_sweep1_shop.cpp pairs each body with its __recomp
