// ===================================================================================================================
// sub_3E9160 [fclShopRoot_Fini]
// (seq, step) -> 0. The ROOT step's fini: for shop type 8 (the shop work record's word +0) the help element
// (sub_40C9A0 of the step payload +16) closes and the root panel 1 is redrawn (sub_3E0C20(work, 1, 1)); every
// other shop releases its list (sub_4003A0 of +12).
// 0x003E9160 sub_3E9160 -- 152 bytes; frame 0x30: ra sp+0x20, s1 sp+0x10 (sq), s0 sp+0x0 (sq)
void sub_3E9160(EEContext& ctx) {
    using namespace hg;
    Gpr v0{ctx, 2}, v1{ctx, 3}, a0{ctx, 4}, a1{ctx, 5}, a2{ctx, 6}, s0{ctx, 16}, s1{ctx, 17}, gp{ctx, 28}, sp{ctx, 29}, ra{ctx, 31};
    // 0x003e9160
    enter(ctx, 15);  // entry check point + this block's cycles
    sp = addiu(sp, -0x30);
    sd(ra, sp, 0x20);
    sq(s1, sp, 0x10);
    sq(s0, sp, 0x0);
    s1 = a1;
    jal(ctx, 0x3E9174u, gen::fn_nmObjPayloadWord12_003c5460);
    s0 = v0;
    a0 = s1;
    jal(ctx, 0x3E9184u, gen::fn_sub_3C5470_003c5470);
    lw(a0, s0, 0);
    v1 = 8;
    if (a0 != v1) {
        // 0x003e91d0
        charge(ctx, 3);
        lw(a0, v0, 12);
        jal(ctx, 0x3E91D4u, gen::fn_sub_4003A0_004003a0);
    } else {
        // 0x003e919c
        charge(ctx, 13);
        lw(a0, v0, 16);
        jal(ctx, 0x3E91A0u, gen::fn_sub_40C9A0_0040c9a0);
        lw(a0, gp, -18024);  // 0x7CE688
        jal(ctx, 0x3E91ACu, gen::fn_nmObjPayloadWord12_003c5460);
        a0 = v0;
        a1 = 1;
        a2 = a1;
        jal(ctx, 0x3E91C0u, gen::fn_sub_3E0C20_003e0c20);
    }
    // 0x003e91dc (the shared epilogue, written out on this path)
    charge(ctx, 7);
    v0 = 0;
    ld(ra, sp, 0x20);
    lq(s1, sp, 0x10);
    lq(s0, sp, 0x0);
    sp = addiu(sp, 0x30);
}

// ===================================================================================================================
// sub_3EAF90 [fclShopArmsCombine_Update]
// (seq, step) -> 0 / nmSeqNullStep. The ARMSCOMBINE (weapon fusion) step's update: hidden (flags bit 1) -> 0; its
// list finished (sub_3FE5D0) -> nmSeqNullStep; a finished sub-list (+16, sub_3FE950) is destroyed; the phases (+8,
// jump table 0x7BBC00): 0 decided; 1 / 2 the base-item list -- the decided row held, the persona stock list
// (sub_3EFDE0 / sub_3FE850), the recipe (sub_401DE0, sub_402400), the yes / no and result messages
// (msgWinRequestMessage, msgWinLastSelection, the item name through sprintf "%d" / sub_3C7BC0), the purchase
// (sub_17C1C0 / sub_174B40), the cancel / close paths (nmCmdListCancelled / CloseNow, sub_3E0C20 panels).
